'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var powf = require( '@stdlib/math/base/special/powf' );
var floorf = require( '@stdlib/math/base/special/floorf' );
var ceilf = require( '@stdlib/math/base/special/ceilf' );
var log10 = require( '@stdlib/math/base/special/log10' );
var MAX_EXP = require( '@stdlib/constants/float32/max-base10-exponent' );
var MIN_EXP_SUBNORMAL = require( '@stdlib/constants/float32/min-base10-exponent-subnormal' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// VARIABLES //

var ZERO = f32( 0.0 );
var ONE = f32( 1.0 );


// MAIN //

/**
* Rounds a single-precision floating-point number to the nearest power of `10` toward negative infinity.
*
* @param {number} x - input value
* @returns {number} rounded value
*
* @example
* var v = floor10f( 3.141592653589793 );
* // returns 1.0
*
* @example
* var v = floor10f( 9.0 );
* // returns 1.0
*
* @example
* var v = floor10f( -0.314 );
* // returns -1.0
*/
function floor10f( x ) {
	var sign;
	var p;
	if (
		isnanf( x ) ||
		isInfinitef( x ) ||
		x === ZERO
	) {
		return x;
	}
	if ( x < ZERO ) {
		x = -x;
		sign = -ONE;
	} else {
		sign = ONE;
	}
	// Solve the equation `10^p = x` for `p`:
	p = f32( log10( x ) );

	// Determine a power of 10 which rounds the input value toward negative infinity:
	if ( sign === ONE ) {
		p = floorf( p );
	} else {
		p = ceilf( p );
	}
	// Handle underflow:
	if ( p <= MIN_EXP_SUBNORMAL ) {
		return f32( sign * ZERO ); // sign-preserving
	}
	// Handle overflow:
	if ( p > MAX_EXP ) {
		return NINF;
	}
	return f32( sign * powf( 10.0, p ) );
}


// EXPORTS //

module.exports = floor10f;
